// GENERATED-STRUCTURE: hand-edited Desktop module. Edit this file, then run
// node hermes_dockyard_plugin/desktop/build.mjs to regenerate plugin.js.
//
// C7 Reports (06/10): the words and structure the Reports tab reads a saved
// report with. Pure functions, no React, so node tests can run them
// (report-vocab.test.mjs).
//
// A report is the Markdown the backend generated and saved
// (dockyard_service.report_generate): a "# title" line, "Generated:" and
// "Generated by:" lines, then "## " sections of "- " lines, a work table
// ("| Ref | Work item | Status | Assignee |") and plain lines. The page shows
// that text as headings, labelled facts, lists and a real table, and drops
// nothing, so the page, Copy and Download say the same things. Reports saved
// before 06/10 carry code names and raw timestamps; they are shown as saved,
// never rewritten.

// The four types the backend accepts, with the words the select has always
// used. `sections` are the "## " headings the backend writes for the type;
// `work` marks a Delivery section that also lists the work items.
export const REPORT_TYPES = Object.freeze([
  { value: 'executive', label: 'Executive summary', sections: ['Configuration', 'Delivery', 'Risks and decisions'], work: false, activity: true },
  { value: 'delivery', label: 'Delivery report', sections: ['Configuration', 'Delivery'], work: true, activity: true },
  { value: 'risk', label: 'Risk and decisions', sections: ['Configuration', 'Risks and decisions'], work: false, activity: false },
  { value: 'full', label: 'Full project report', sections: ['Configuration', 'Delivery', 'Risks and decisions'], work: true, activity: true },
])
const ACTIVITY = 'Recent activity'

const sentence = (value) => {
  const words = String(value ?? '').replace(/[._]+/g, ' ').replace(/\s+/g, ' ').trim()
  return words ? words[0].toUpperCase() + words.slice(1) : ''
}
export const reportType = (value) => REPORT_TYPES.find((type) => type.value === value) ?? null
export const reportTypeLabel = (value) => reportType(value)?.label ?? (sentence(value) || 'Report')
// Whether a report of this type can carry recent activity at all.
export const takesActivity = (value) => reportType(value)?.activity ?? false

// The sections a new report of this type will have, in order.
export function reportSections(value, includeActivity) {
  const type = reportType(value)
  if (!type) return []
  return type.activity && includeActivity ? [...type.sections, ACTIVITY] : [...type.sections]
}

// The one-line hint under the Generate controls.
export function reportHint(value, includeActivity) {
  const type = reportType(value)
  if (!type) return ''
  const parts = reportSections(value, includeActivity).map((section) => (section === 'Delivery' && type.work ? 'Delivery, with the work list' : section))
  return `Sections: ${parts.join(' · ')}${type.activity ? '' : '. Risk reports never include recent activity.'}`
}

// "6 Oct 2026, 12:58" in the person's own time zone (or `timeZone`).
export function reportWhen(value, timeZone) {
  if (!value) return ''
  const at = new Date(value)
  if (Number.isNaN(at.getTime())) return ''
  const parts = new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23', timeZone }).formatToParts(at)
  const part = (name) => parts.find((entry) => entry.type === name)?.value ?? ''
  return `${part('day')} ${part('month')} ${part('year')}, ${part('hour')}:${part('minute')}`
}

const unescape = (text) => text.replace(/\\([|`])/g, '$1')
// "Label: value" with a short, letters-only label. A line that starts with a
// time ("6 Oct 2026, 11:58 UTC — ...") or a code name is a plain list item.
const FACT = /^([A-Za-z][A-Za-z ()/-]{0,38}): (.+)$/
const SEPARATOR = /^\|(\s*:?-{3,}:?\s*\|)+$/
const cells = (line) => {
  const inner = line.trim().replace(/^\|/, '').replace(/(?<!\\)\|$/, '')
  return inner.split(/(?<!\\)\|/).map((cell) => unescape(cell.trim()))
}

// The saved Markdown as { title, generated, generatedBy, blocks }. Blocks are
// { kind: 'heading', text }, { kind: 'text', text }, { kind: 'list', items }
// (each item { text } or { text, label, value }) and
// { kind: 'table', head, rows }.
export function parseReport(markdown) {
  const doc = { title: '', generated: '', generatedBy: '', blocks: [] }
  let open = null
  const lines = String(markdown ?? '').replace(/\r\n?/g, '\n').split('\n')
  for (const raw of lines) {
    const line = raw.trim()
    if (!line) { open = null; continue }
    const top = doc.blocks.length === 0
    if (top && !doc.title && line.startsWith('# ')) { doc.title = unescape(line.slice(2).trim()); continue }
    if (top && !doc.generated && line.startsWith('Generated: ')) { doc.generated = unescape(line.slice(11).trim()); continue }
    if (top && !doc.generatedBy && line.startsWith('Generated by: ')) { doc.generatedBy = unescape(line.slice(14).trim()); continue }
    const heading = /^#{1,6} (.+)$/.exec(line)
    if (heading) {
      open = null
      doc.blocks.push({ kind: 'heading', text: unescape(heading[1].trim()) })
      continue
    }
    if (line.startsWith('|')) {
      if (open?.kind === 'table') {
        if (open.rows.length === 0 && SEPARATOR.test(line)) continue
        open.rows.push(cells(line))
      } else {
        open = { kind: 'table', head: cells(line), rows: [] }
        doc.blocks.push(open)
      }
      continue
    }
    const bullet = /^[-*] (.*)$/.exec(line)
    if (bullet) {
      if (open?.kind !== 'list') {
        open = { kind: 'list', items: [] }
        doc.blocks.push(open)
      }
      const text = unescape(bullet[1].trim())
      const fact = FACT.exec(text)
      open.items.push(fact ? { text, label: fact[1], value: fact[2] } : { text })
      continue
    }
    open = null
    doc.blocks.push({ kind: 'text', text: unescape(line) })
  }
  return doc
}
